const formatarData = (data) => {
  const d = new Date(data);
  return d.toLocaleDateString('pt-BR');
};

const formatarDataHora = (data) => {
  if (!data) return '-';
  const d = new Date(data);
  return d.toLocaleString('pt-BR');
};

const allItems = $input.all();
const dataInicio = formatarData($('Webhook1').first().json.body.dataInicial);
const dataFim = formatarData($('Webhook1').first().json.body.dataFinal);

// Separa chamados (têm Num_Chamado) de categorias (têm Tempo_Total_Formatado)
const chamados = allItems.filter(i => i.json.Num_Chamado != null);
const categorias = allItems.filter(i => i.json.Tempo_Total_Formatado != null && i.json.Num_Chamado == null);

const cliente = chamados.length > 0 ? chamados[0].json.Cliente : 'Cliente';

// Totais
let totalSegundos = 0;
let violacoes = 0;

let rowsChamados = '';

for (const item of chamados) {
  totalSegundos += Number(item.json.Tempo_Trabalhado_Segundos || 0);

  const badgeTipo = item.json.TipoChamado === 'Incidente'
    ? `<span style="display:inline-block;font-size:11px;font-weight:500;padding:2px 6px;border-radius:4px;background:#FAECE7;color:#993C1D;">Incidente</span>`
    : `<span style="display:inline-block;font-size:11px;font-weight:500;padding:2px 6px;border-radius:4px;background:#E6F1FB;color:#185FA5;">Requisição</span>`;

  rowsChamados += `
  <tr>
    <td style="padding:8px;border-bottom:0.5px solid #e5e7eb;color:#111;">
      ${item.json.Num_Chamado}
    </td>

    <td style="padding:8px;border-bottom:0.5px solid #e5e7eb;">
      ${badgeTipo}
    </td>

    <td style="padding:8px;border-bottom:0.5px solid #e5e7eb;color:#111;word-break:break-word;">
      ${item.json.Titulo || '-'}
    </td>

    <td class="hide-mobile" style="padding:8px;border-bottom:0.5px solid #e5e7eb;">
      ${item.json.Categoria || 'Sem categoria'}
    </td>

    <td class="hide-mobile" style="padding:8px;border-bottom:0.5px solid #e5e7eb;">
      ${item.json.Tecnico || '-'}
    </td>

    <td class="hide-mobile" style="padding:8px;border-bottom:0.5px solid #e5e7eb;">
      ${formatarDataHora(item.json.DataHoraSolucao)}
    </td>

    <td class="hide-mobile" style="padding:8px;border-bottom:0.5px solid #e5e7eb;">
      ${formatarDataHora(item.json.DataHoraFechamento)}
    </td>

    <td style="padding:8px;border-bottom:0.5px solid #e5e7eb;">
      ${item.json.Tempo_Trabalhado_Formatado || '00:00:00'}
    </td>
  </tr>`;
}

// Total formatado
const totalFormatado = new Date(totalSegundos * 1000).toISOString().substring(11, 19);
const pctSLA = chamados.length > 0 ? ((1 - violacoes / chamados.length) * 100).toFixed(1) : '0.0';
const corSLA = parseFloat(pctSLA) >= 90 ? '#0F6E56' : '#c0392b';
const corViolacoes = violacoes > 0 ? '#c0392b' : '#0F6E56';

let rowsCategorias = '';
for (const item of categorias) {
  rowsCategorias += `
    <tr>
      <td style="padding:10px;border-bottom:0.5px solid #e5e7eb;color:#111;">${item.json.Categoria}</td>
      <td style="padding:10px;border-bottom:0.5px solid #e5e7eb;color:#111;text-align:right;">${item.json.Tempo_Total_Formatado}</td>
    </tr>`;
}

const dataGeracao = new Date().toLocaleString('pt-BR');

const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
  body { margin:0; padding:0; background:#f0f2f5; font-family:Arial,sans-serif; }

  @media only screen and (max-width: 600px) {
    .container { padding: 0 8px !important; }
    .card { border-radius: 0 !important; }
    .content { padding: 16px !important; }
    .hide-mobile { display: none !important; }
    .table td, .table th { font-size: 11px !important; padding: 6px !important; }
    .metric { display:block !important; width:100% !important; margin-bottom:10px; }
    .title { font-size:16px !important; }
  }
</style>
</head>

<body>

<div class="container" style="max-width:780px;margin:24px auto;padding:0 12px;">
<div class="card" style="background:#ffffff;border-radius:10px;overflow:hidden;border:1px solid #e0e0e0;">

  <!-- HEADER -->
  <div style="background:#1a3a5c;padding:24px;">
    <div style="font-size:11px;color:#7eadd4;font-weight:bold;letter-spacing:0.08em;text-transform:uppercase;margin-bottom:6px;">
      Mindworks · Relatório
    </div>
    <div class="title" style="font-size:20px;font-weight:bold;color:#ffffff;">
      ${cliente}
    </div>
    <div style="margin-top:10px;background:rgba(255,255,255,0.12);border-radius:6px;padding:5px 12px;font-size:12px;color:#d4e8f5;display:inline-block;">
      ${dataInicio} – ${dataFim}
    </div>
  </div>

  <div class="content" style="padding:24px;">

    <!-- MÉTRICAS -->
    <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;">
      <tr>
        <td class="metric" width="25%" style="padding:6px;">
          <div style="background:#f5f6f8;border-radius:8px;padding:12px;">
            <div style="font-size:10px;color:#666;text-transform:uppercase;">Chamados</div>
            <div style="font-size:20px;font-weight:bold;">${chamados.length}</div>
          </div>
        </td>

        <td class="metric" width="25%" style="padding:6px;">
          <div style="background:#f5f6f8;border-radius:8px;padding:12px;">
            <div style="font-size:10px;color:#666;text-transform:uppercase;">Horas</div>
            <div style="font-size:20px;font-weight:bold;">${totalFormatado}</div>
          </div>
        </td>

        <td class="metric" width="25%" style="padding:6px;">
          <div style="background:#f5f6f8;border-radius:8px;padding:12px;">
            <div style="font-size:10px;color:#666;text-transform:uppercase;">SLA</div>
            <div style="font-size:20px;font-weight:bold;color:${corSLA};">${pctSLA}%</div>
          </div>
        </td>

        <td class="metric" width="25%" style="padding:6px;">
          <div style="background:#f5f6f8;border-radius:8px;padding:12px;">
            <div style="font-size:10px;color:#666;text-transform:uppercase;">Violações</div>
            <div style="font-size:20px;font-weight:bold;color:${corViolacoes};">${violacoes}</div>
          </div>
        </td>
      </tr>
    </table>

    <!-- CHAMADOS -->
    <div style="font-size:11px;font-weight:bold;color:#666;text-transform:uppercase;margin-bottom:8px;border-bottom:1px solid #e5e7eb;padding-bottom:6px;">
      Chamados
    </div>

    <table width="100%" cellpadding="0" cellspacing="0" class="table" style="font-size:12px;">
      <thead>
        <tr style="background:#f9fafb;">
          <th style="padding:8px;text-align:left;">ID</th>
          <th style="padding:8px;text-align:left;">Tipo</th>
          <th style="padding:8px;text-align:left;">Título</th>
          <th class="hide-mobile" style="padding:8px;text-align:left;">Categoria</th>
          <th class="hide-mobile" style="padding:8px;text-align:left;">Analista</th>
          <th class="hide-mobile" style="padding:8px;text-align:left;">Solução</th>
          <th class="hide-mobile" style="padding:8px;text-align:left;">Fechamento</th>
          <th style="padding:8px;text-align:left;">Horas</th>
        </tr>
      </thead>
      <tbody>
        ${rowsChamados}

        <tr style="background:#f5f6f8;">
          <td colspan="7" style="padding:8px;font-weight:bold;">Total</td>
          <td style="padding:8px;font-weight:bold;">${totalFormatado}</td>
        </tr>
      </tbody>
    </table>

    <!-- CATEGORIAS -->
    <div style="font-size:11px;font-weight:bold;color:#666;text-transform:uppercase;margin:20px 0 8px;border-bottom:1px solid #e5e7eb;padding-bottom:6px;">
      Categorias
    </div>

    <table width="100%" cellpadding="0" cellspacing="0" style="font-size:12px;">
      <thead>
        <tr style="background:#f9fafb;">
          <th style="padding:8px;text-align:left;">Categoria</th>
          <th style="padding:8px;text-align:right;">Horas</th>
        </tr>
      </thead>
      <tbody>
        ${rowsCategorias}
      </tbody>
    </table>

  </div>

  <!-- FOOTER -->
  <div style="padding:14px 24px;border-top:1px solid #e5e7eb;font-size:11px;color:#999;">
    Gerado automaticamente em ${dataGeracao}
  </div>

</div>
</div>

</body>
</html>`;

return [{ json: { html } }];

const formatarDataHora = (data) => {
  if (!data) return '-';
  const d = new Date(data);
  return d.toLocaleDateString('pt-BR');
};

const items = $input.all();
const dataInicio = formatarDataHora($('Edit Fields3').first().json.data_inicio)
const dataFim = formatarDataHora($('Edit Fields3').first().json.data_fim)
const dataGeracao = new Date().toLocaleString('pt-BR');

// Função para pegar apenas o último nome do completename
function getNome(completename) {
  if (!completename) return '-';
  const partes = completename.split('>');
  return partes[partes.length - 1].trim();
}

// Formatar horas (ex: 2.3333 → 02:20)
function formatarHoras(decimal) {
  const horas = Math.floor(decimal);
  const minutos = Math.round((decimal - horas) * 60);
  return `${String(horas).padStart(2, '0')}:${String(minutos).padStart(2, '0')}`;
}

let totalContratadas = 0;
let totalTrabalhadas = 0;

let rows = '';

for (const item of items) {
  const nome = getNome(item.json.completename);
  const horasContratadas = Number(item.json.Horas_Contratadas || 0);
  const horasTrabalhadas = Number(item.json.Horas_Trabalhadas || 0);

  totalContratadas += horasContratadas;
  totalTrabalhadas += horasTrabalhadas;

  const percentual = horasContratadas > 0
    ? ((horasTrabalhadas / horasContratadas) * 100).toFixed(1)
    : '0.0';

  const corPercentual =
    percentual >= 100 ? '#c0392b' :
    percentual >= 80 ? '#f39c12' :
    '#0F6E56';

  rows += `
    <tr>
      <td style="padding:8px;border-bottom:1px solid #e5e7eb;">
        ${nome}
      </td>

      <td style="padding:8px;border-bottom:1px solid #e5e7eb;text-align:right;">
        ${formatarHoras(horasContratadas)}
      </td>

      <td style="padding:8px;border-bottom:1px solid #e5e7eb;text-align:right;">
        ${formatarHoras(horasTrabalhadas)}
      </td>

      <td style="padding:8px;border-bottom:1px solid #e5e7eb;text-align:right;font-weight:bold;color:${corPercentual};">
        ${percentual}%
      </td>
    </tr>
  `;
}

const totalPercentual = totalContratadas > 0
  ? ((totalTrabalhadas / totalContratadas) * 100).toFixed(1)
  : '0.0';

const corTotal =
  totalPercentual >= 100 ? '#c0392b' :
  totalPercentual >= 80 ? '#f39c12' :
  '#0F6E56';

const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
  body { margin:0; padding:0; background:#f0f2f5; font-family:Arial,sans-serif; }

  @media only screen and (max-width: 600px) {
    .container { padding: 0 8px !important; }
    .content { padding: 16px !important; }
    .hide-mobile { display: none !important; }
    .table td, .table th { font-size: 11px !important; padding: 6px !important; }
    .metric { display:block !important; width:100% !important; margin-bottom:10px; }
  }
</style>
</head>

<body>

<div class="container" style="max-width:720px;margin:24px auto;padding:0 12px;">
<div style="background:#fff;border-radius:10px;border:1px solid #e5e7eb;overflow:hidden;">

  <!-- HEADER -->
  <div style="background:#1a3a5c;padding:20px;color:#fff;">
    <div style="font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:#7eadd4;">
      Relatório de Horas
    </div>
    <div style="font-size:18px;font-weight:bold;margin-top:4px;">
      Horas por Cliente
    </div>
    <div style="margin-top:8px;font-size:12px;color:#d4e8f5;">
      ${dataInicio} – ${dataFim}
    </div>
  </div>

  <div class="content" style="padding:20px;">



    <!-- TABELA -->
    <table width="100%" cellpadding="0" cellspacing="0" class="table" style="font-size:12px;">
      <thead>
        <tr style="background:#f9fafb;">
          <th style="padding:8px;text-align:left;">Cliente</th>
          <th style="padding:8px;text-align:right;">Contratadas</th>
          <th style="padding:8px;text-align:right;">Trabalhadas</th>
          <th style="padding:8px;text-align:right;">%</th>
        </tr>
      </thead>
      <tbody>
        ${rows}

        <tr style="background:#f5f6f8;">
          <td style="padding:8px;font-weight:bold;">Total</td>
          <td style="padding:8px;text-align:right;font-weight:bold;">
            ${formatarHoras(totalContratadas)}
          </td>
          <td style="padding:8px;text-align:right;font-weight:bold;">
            ${formatarHoras(totalTrabalhadas)}
          </td>
          <td style="padding:8px;text-align:right;font-weight:bold;color:${corTotal};">
            ${totalPercentual}%
          </td>
        </tr>
      </tbody>
    </table>

  </div>

  <!-- FOOTER -->
  <div style="padding:12px 20px;border-top:1px solid #e5e7eb;font-size:11px;color:#999;">
    Gerado automaticamente em ${dataGeracao}
  </div>

</div>
</div>

</body>
</html>`;


return [
  {
    json: {
      html
    }
  }
];
